def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if not hasattr(self, "_keys") or self._keys is None:
        return []
    return list(self._keys.keys())

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = cls._protocol_handlers.get(protocol_version)
        return {protocol_version: handler} if handler is not None else {}
    return dict(cls._protocol_handlers)

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(session, *args, **kwargs):
            tx_config = {}
            if metadata is not None:
                tx_config["metadata"] = metadata
            if timeout is not None:
                tx_config["timeout"] = timeout
            return session.write_transaction(func, *args, **kwargs, tx_config=tx_config)
        return wrapper
    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        if isinstance(self._items, dict):
            return list(self._items.values())
        else:
            # Assume a sequence (list, tuple, etc.)
            return list(self._items)

    # Otherwise, filter by the provided keys or indices
    results = []
    for key in keys:
        # Handle integer indices for sequence types
        if isinstance(key, int) and not isinstance(self._items, dict):
            try:
                results.append(self._items[key])
            except (IndexError, TypeError):
                # Skip invalid indices
                continue
        else:
            # Handle key lookup for mapping types
            try:
                results.append(self._items[key])
            except (KeyError, TypeError):
                # Skip missing keys
                continue
    return results

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return dict(zip(self._keys, self._values))
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            field_name = self._keys[key]
            result[field_name] = self._values[key]
        else:
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop 2 bytes")
    last_two = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(last_two, byteorder='big', signed=False)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    namespace = {}
    annotations = {}
    for item in fields:
        if isinstance(item, str):
            field_name = item
            field_type = 'typing.Any'
        elif isinstance(item, tuple):
            if len(item) == 2:
                field_name, field_type = item
            else:
                raise TypeError(f'Invalid field: {item!r}')
        else:
            raise TypeError(f'Invalid field: {item!r}')
        annotations[field_name] = field_type
    namespace['__annotations__'] = annotations
    namespace['srid_map'] = srid_map
    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    nums = []
    current = ''
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                nums.append(int(current))
                current = ''
    if current:
        nums.append(int(current))
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}
        @wraps(user_function)
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                value = cache[key]
                # move to end to mark as recently used
                del cache[key]
                cache[key] = value
                return value
            except KeyError:
                value = user_function(*args, **kwargs)
                cache[key] = value
                if maxsize is not None and len(cache) > maxsize:
                    cache.popitem(last=False)
                return value
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper
    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = (tuple((type(a), a) for a in args),
                       tuple((k, type(v), v) for k, v in sorted(kwargs.items())))
            else:
                key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find the least frequently used key(s)
                min_freq = min(freq.values())
                # Evict one key with the minimum frequency
                for evict_key, f in freq.items():
                    if f == min_freq:
                        del cache[evict_key]
                        del freq[evict_key]
                        break
            cache[key] = result
            freq[key] = 1
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key in self._value:
        return self._value[key]
    else:
        self._value[key] = default
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            name = name[:-len(suffix)]
    return name

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    classes = self.__class__.mro() if all else [self.__class__]
    seen = set()
    for cls in classes:
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if name in seen:
                continue
            seen.add(name)
            if callable(value):
                continue
            desc = getattr(value, '__doc__', '')
            if desc is None:
                desc = ''
            result.append((name, desc))
    result.sort(key=lambda x: x[0])
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Helper to collect names from a single class
    def _collect(cls):
        # Prefer annotations (used by dataclasses, pydantic, attrs, etc.)
        if hasattr(cls, "__annotations__"):
            return list(cls.__annotations__.keys())
        # Next, check for __slots__
        if hasattr(cls, "__slots__"):
            slots = cls.__slots__
            if isinstance(slots, str):
                slots = (slots,)
            return list(slots)
        # Fallback: non-callable, non-private class attributes
        return [
            name
            for name, value in vars(cls).items()
            if not callable(value) and not name.startswith("_")
        ]

    # Start with the current class
    names = _collect(self.__class__)

    if all:
        # Include attributes from base classes (excluding object)
        for base in self.__class__.__mro__[1:]:
            if base is object:
                continue
            for name in _collect(base):
                if name not in names:
                    names.append(name)

    return names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the sequence is a broken interface, return it as is
    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    # If the sequence is an interface or an implements spec, add it to output
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        # Otherwise, recursively normalize each element in the sequence
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dictionary
    self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # Preserve the existing number of bins
        if hasattr(self, "bins"):
            self.bins = [self.initial_value] * len(self.bins)
        else:
            # If bins were never created, create them with the initial value
            self.bins = [self.initial_value]
    else:
        # Use the make_bins method to create a fresh set of bins
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    for point in self:
        # Expect point to be a tuple (coord, value)
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            # If the graph yields only values, treat the whole point as value
            coord, value = None, point

        # Convert coordinate to string
        if coord is None:
            coord_str = ""
        elif isinstance(coord, (list, tuple, set)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)

        # Convert value to string
        if value is None:
            value_str = ""
        elif isinstance(value, (list, tuple, set)):
            value_str = separator.join(map(str, value))
        elif isinstance(value, dict):
            value_str = separator.join(f"{k}={v}" for k, v in value.items())
        else:
            value_str = str(value)

        # Combine coordinate and value parts
        if coord_str and value_str:
            line = coord_str + separator + value_str
        elif coord_str:
            line = coord_str
        else:
            line = value_str
        lines.append(line)

    csv_text = "\n".join(lines)
    if header is not None:
        csv_text = header + "\n" + csv_text
    return csv_text

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq itself is a FillRequest instance, it's valid
    if isinstance(seq, FillRequest):
        return True

    # If seq is a Source sequence, it's not valid
    if isinstance(seq, Source):
        return False

    # Try to iterate over seq and look for at least one FillRequest element
    try:
        return any(isinstance(item, FillRequest) for item in seq)
    except TypeError:
        # seq is not iterable
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Simple regex patterns for demonstration purposes
    key_regex = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    value_regex = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            if not key_regex.match(key):
                errors.append({repr(key): f"Label key '{key}' does not match the regex [...]"})

        # Validate value
        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({repr(value): f"Label value '{value}' does not match the regex [...]"})
        elif isinstance(value, list):
            for elem in value:
                if not isinstance(elem, str):
                    errors.append({repr(elem): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(elem):
                        errors.append({repr(elem): f"Label value '{elem}' does not match the regex [...]"})
        else:
            errors.append({repr(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    new_dict = {}
    for key, value in manifest_dict.items():
        # Copy identifying fields at the top level
        if first_level and key in ("apiVersion", "kind"):
            new_dict[key] = value
            continue
        if first_level and key == "metadata":
            new_dict[key] = {}
            if isinstance(value, dict):
                for subkey in ("name", "namespace"):
                    if subkey in value:
                        new_dict[key][subkey] = value[subkey]
            continue

        # Recurse into nested dictionaries
        if isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Preserve lists as-is (they will be processed by the list helper)
        elif isinstance(value, list):
            new_dict[key] = value
        # Replace all other values with None
        else:
            new_dict[key] = None
    return new_dict

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Ensure the manifest list is long enough
    for idx, field in enumerate(observer_schema):
        # Determine field metadata
        if isinstance(field, dict):
            field_name = field.get("name")
            field_type = field.get("type", "primitive")
            nested_schema = field.get("schema", [])
        else:
            # Assume primitive field represented by its name
            field_name = field
            field_type = "primitive"
            nested_schema = []

        # Extend the manifest list if necessary
        if len(last_applied_manifest) <= idx:
            last_applied_manifest.extend([None] * (idx - len(last_applied_manifest) + 1))

        # Get the corresponding value from the response if available
        resp_val = response[idx] if idx < len(response) else None

        # Handle nested structures
        if field_type == "dict":
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = {}
            if resp_val is not None:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], nested_schema, resp_val
                )
        elif field_type == "list":
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = []
            if resp_val is not None:
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], nested_schema, resp_val
                )
        else:
            # Primitive field: set only if not already present
            if last_applied_manifest[idx] is None and resp_val is not None:
                last_applied_manifest[idx] = resp_val
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not found in response")
        # If the schema indicates a nested dict, recurse
        if isinstance(sub_schema, dict):
            # Ensure the nested dict exists in the manifest
            if field not in last_applied_manifest or not isinstance(last_applied_manifest[field], dict):
                last_applied_manifest[field] = {}
            # Recurse into the nested structure
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
        else:
            # Leaf field: set value if not already present
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]
    return last_applied_manifest

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    return f"{prefix}{self.status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to locate the log attribute; fall back to common names.
    log = getattr(self, 'validation_log', None) or getattr(self, 'log', None) or getattr(self, 'entries', None) or []
    lines = []
    for entry in log:
        if isinstance(entry, dict):
            status = entry.get('status')
            message = entry.get('message')
            if status is not None and message is not None:
                lines.append(f"{prefix}{status}: {message}")
            else:
                lines.append(f"{prefix}{entry}")
        else:
            lines.append(f"{prefix}{entry}")
    return "\n".join(lines)

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")
    if not hasattr(prior, "version"):
        raise AttributeError("prior object lacks 'version' attribute")
    if not hasattr(self, "version"):
        raise AttributeError("current object lacks 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(f"prior version ({prior.version}) must be older than current version ({self.version})")
    if not hasattr(prior, "items"):
        raise AttributeError("prior object lacks 'items' attribute")
    if not hasattr(self, "items"):
        raise AttributeError("current object lacks 'items' attribute")
    missing = set(prior.items) - set(self.items)
    if missing:
        raise ValueError(f"prior contains items not present in current inventory: {missing}")
    for key in prior.items:
        curr_item = self.items[key]
        prior_item = prior.items[key]
        if curr_item != prior_item:
            raise ValueError(f"Item '{key}' differs between current and prior inventory")
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure inventory is a mapping of version -> mapping of logical_path -> content_file
    # If inventory is a list of (version, mapping) tuples, convert to dict
    if isinstance(inventory, list):
        inv_dict = {ver: mapping for ver, mapping in inventory}
    else:
        inv_dict = inventory

    # Sort versions in natural order if possible; fallback to string comparison
    try:
        sorted_versions = sorted(inv_dict.keys(), key=lambda v: tuple(map(int, v.split('.'))))
    except Exception:
        sorted_versions = sorted(inv_dict.keys())

    # Find the index of the requested version
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        # If the exact version is not found, find the first version greater than the requested one
        start_index = next((i for i, v in enumerate(sorted_versions) if v > version), len(sorted_versions))

    # Build the mapping
    logical_map = {}
    for v in sorted_versions[start_index:]:
        mapping = inv_dict.get(v, {})
        for logical_path, content_file in mapping.items():
            logical_map.setdefault(logical_path, set()).add(content_file)

    return logical_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if "files" not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    manifest_set = set(manifest_files)

    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")

        if "path" not in entry:
            raise ValueError(f"File entry at index {idx} missing required 'path' key")

        path = entry["path"]
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block is not present in the manifest")

        # Optional: validate optional fields
        if "hash" in entry and not isinstance(entry["hash"], str):
            raise ValueError(f"Hash for file '{path}' must be a string")

        if "size" in entry and not isinstance(entry["size"], int):
            raise ValueError(f"Size for file '{path}' must be an integer")

    # If all checks pass, return True
    return True

def files_list(path):
    """Return the files in `path`"""
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))]
    return []

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Derive the original filename by stripping the language suffix
    base, ext = os.path.splitext(file_path)
    if '-' in base:
        original_base = base.rsplit('-', 1)[0]
    else:
        original_base = base
    original = original_base + ext

    # Ensure the renditions dictionary exists
    if not hasattr(self, 'renditions'):
        self.renditions = {}

    # Store the rendition
    if original not in self.renditions:
        self.renditions[original] = {}
    self.renditions[original][lang] = file_path

    return self.renditions[original]

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    asset_map = {}
    for fname in os.listdir(file_path):
        if fname.startswith(basename):
            src = os.path.join(file_path, fname)
            dst = os.path.join(self._asset_path, fname)
            shutil.copy2(src, dst)
            asset_map[fname] = dst
    return asset_map

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    packages = {}
    # First pass: identify XML files and their basenames
    xml_bases = {}
    with zipfile.ZipFile(zip_path, 'r') as zin:
        for zinfo in zin.infolist():
            if zinfo.is_dir():
                continue
            name = zinfo.filename
            if name.lower().endswith('.xml'):
                base = os.path.splitext(os.path.basename(name))[0]
                xml_bases[base] = name
                packages[base] = {}
        # Second pass: read all files and assign them to the appropriate package
        for zinfo in zin.infolist():
            if zinfo.is_dir():
                continue
            name = zinfo.filename
            # Determine which package this file belongs to
            matched_base = None
            for base in xml_bases:
                # Match if the file name starts with the base (handles nested paths)
                if name == base or name.startswith(base + '/') or name.startswith(base):
                    matched_base = base
                    break
            if matched_base:
                content = zin.read(name)
                packages[matched_base][name] = content
    return packages

def fix_namespace_prefix_w(content):
