def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import pprint
    if debug:
        header = f"{self.__class__.__name__} at {hex(id(self))}\n"
    else:
        header = ""
    if hasattr(self, "__dict__"):
        body = pprint.pformat(self.__dict__, indent=indent)
    else:
        body = repr(self)
    return header + body

def normalized(self):
        """
        Return a version of this object represented entirely using integer
        values for the relative attributes.

        >>> relativedelta(days=1.5, hours=2).normalized()
        relativedelta(days=+1, hours=+14)

        :return:
            Returns a :class:`dateutil.relativedelta.relativedelta` object.
        """
        # Attributes that can have fractional parts
        attrs = ['years', 'months', 'days', 'weeks',
                 'hours', 'minutes', 'seconds', 'microseconds', 'leapdays']
        kwargs = {}
        # Temporary storage for carry-over from higher to lower units
        carry = {'days': 0, 'hours': 0, 'minutes': 0, 'seconds': 0, 'microseconds': 0}

        for attr in attrs:
            val = getattr(self, attr)
            if val is None:
                continue
            int_part = int(val)
            frac = val - int_part
            kwargs[attr] = int_part

            # Convert fractional part to lower unit
            if attr == 'days' and frac:
                carry['hours'] += int(round(frac * 24))
            elif attr == 'hours' and frac:
                carry['minutes'] += int(round(frac * 60))
            elif attr == 'minutes' and frac:
                carry['seconds'] += int(round(frac * 60))
            elif attr == 'seconds' and frac:
                carry['microseconds'] += int(round(frac * 1_000_000))

        # Add carry-over to the appropriate fields
        if 'hours' in kwargs:
            kwargs['hours'] += carry['hours']
        else:
            kwargs['hours'] = carry['hours']

        if 'minutes' in kwargs:
            kwargs['minutes'] += carry['minutes']
        else:
            kwargs['minutes'] = carry['minutes']

        if 'seconds' in kwargs:
            kwargs['seconds'] += carry['seconds']
        else:
            kwargs['seconds'] = carry['seconds']

        if 'microseconds' in kwargs:
            kwargs['microseconds'] += carry['microseconds']
        else:
            kwargs['microseconds'] = carry['microseconds']

        return relativedelta(**kwargs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        with open('VERSION', 'r') as f:
            return f.read().strip()
    except Exception:
        return 'unknown'

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")

    # If style is a callable, delegate rendering to it
    if callable(style):
        return style(pieces)

    # Standard style handling
    if style == 'html':
        return ''.join(f'<p>{piece}</p>' for piece in pieces)
    elif style == 'markdown':
        return '\n\n'.join(f'## {piece}' if isinstance(piece, str) else str(piece) for piece in pieces)
    elif style == 'plain':
        return '\n'.join(str(piece) for piece in pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    return '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Retrieve all objects in the hierarchy
    try:
        objects = self._get_all_objects()
    except AttributeError:
        objects = getattr(self, '_objects', [])
    for obj in objects:
        num_objects += 1
        is_valid = True
        if validate_objects:
            if hasattr(obj, 'validate'):
                try:
                    obj.validate()
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Validation failed for {obj}: {e}")
            else:
                if show_warnings:
                    print(f"Object {obj} has no validate method")
                is_valid = False
        if check_digests and is_valid:
            if hasattr(obj, 'check_digest'):
                try:
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f"Digest mismatch for {obj}")
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Digest check error for {obj}: {e}")
            else:
                if show_warnings:
                    print(f"Object {obj} has no check_digest method")
                is_valid = False
        if is_valid:
            good_objects += 1
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("self.root_inventory must be a dict mapping file paths to digests")

    # Prepare a place to record digest differences
    self.different_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{vdir}'")

        with open(inv_path, "r", encoding="utf-8") as fh:
            try:
                inv = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Failed to parse inventory in '{vdir}': {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in '{vdir}' must be a JSON object mapping file paths to digests")

        # Check that every file in the inventory exists in the root inventory
        for path, digest in inv.items():
            if path not in self.root_inventory:
                raise ValueError(f"Inventory in '{vdir}' contains unknown file '{path}'")
            root_digest = self.root_inventory[path]
            if digest != root_digest:
                self.different_digests.setdefault(path, []).append((vdir, digest))

        # Check that the inventory does not contain any files that are not in the root inventory
        for path in inv:
            if path not in self.root_inventory:
                raise ValueError(f"Inventory in '{vdir}' contains unexpected file '{path}'")

    # After validation, self.different_digests holds any digest mismatches
    return self.different_digests if self.different_digests else None

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, fnmatch

    if not os.path.exists(path):
        return f"Path does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"Cannot list directory: {e}"
        namaste_files = [f for f in entries if fnmatch.fnmatch(f, '0=*')]
        if len(namaste_files) == 0:
            return 'root'
        elif len(namaste_files) == 1:
            return 'object'
        else:
            return f"Multiple Namaste files found: {namaste_files}"
    return f"Unknown path type: {path}"

def amend_bzparams(self, params, bug_ids):
