def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples, merging MappingNode values
    with the same key. For non-MappingNode values, the last value wins.
    """
    def merge_mapping_nodes(m1, m2):
        # Merge the two MappingNode values recursively
        merged_list = deep_merge_nodes(m1.value + m2.value)
        return MappingNode(tag=m1.tag, value=merged_list)

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_value = merged[key]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                merged[key] = (existing_key_node, merged_value)
            else:
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)
    return list(merged.values())

