def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')
    # NOTE: Subparsers should be added by the caller before invoking this function.
    # Parse the arguments, allowing unknown arguments to be ignored.
    parsed, _ = parser.parse_known_args(unparsed_arguments)
    if getattr(parsed, 'subparser_name', None):
        return {parsed.subparser_name: parsed}
    else:
        return {'global': parsed}

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not dicts:
        return {}
    counters = [Counter(d) for d in dicts]
    total = sum(counters, Counter())
    return dict(total)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    for key, value in url_args.items():
        if value is None:
            continue
        placeholder_braces = '{' + key + '}'
        placeholder_colon = ':' + key
        url = url.replace(placeholder_braces, str(value))
        url = url.replace(placeholder_colon, str(value))
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ("none", "null", "undefined"):
            return True
    return False

