def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        # digits are least significant first, reverse to get most significant first
        result = ''.join(reversed(digits))
    # Apply padding if requested
    if padding is not None:
        if padding > len(result):
            result = alphabet[0] * (padding - len(result)) + result
    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        return value
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove leading and trailing single or double quotes
    return re.sub(r'^[\'"]|[\'"]$', '', name)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Determine the extraction directory
    if filename:
        extract_dir = os.path.join(tmp_path, filename)
    else:
        base = os.path.basename(archive_path)
        # Handle double extensions like .tar.gz
        if base.endswith('.tar.gz'):
            name = base[:-7]
        elif base.endswith('.tar.bz2'):
            name = base[:-8]
        elif base.endswith('.tar.xz'):
            name = base[:-7]
        else:
            name, _ = os.path.splitext(base)
        extract_dir = os.path.join(tmp_path, name)

    os.makedirs(extract_dir, exist_ok=True)

    # Build the extraction command based on the archive type
    if archive_path.endswith('.tar.gz'):
        cmd = ['tar', '-xzf', archive_path, '-C', extract_dir]
    elif archive_path.endswith('.tar.bz2'):
        cmd = ['tar', '-xjf', archive_path, '-C', extract_dir]
    elif archive_path.endswith('.tar.xz'):
        cmd = ['tar', '-xJf', archive_path, '-C', extract_dir]
    elif archive_path.endswith('.tar'):
        cmd = ['tar', '-xf', archive_path, '-C', extract_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', extract_dir]
    else:
        raise ValueError(f'Unsupported archive type: {archive_path}')

    # Execute the extraction
    subprocess.run(cmd, check=True)

    # Return the file repository URL
    return f'file://{extract_dir}'

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError:
        return ''
    files = [f.strip() for f in output.decode().splitlines() if f.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string, got %r" % frequency)

    import re
    m = re.match(r'^\s*(\d+)\s*([a-zA-Z]+)\s*$', frequency)
    if not m:
        raise ValueError("Could not parse frequency: %r" % frequency)

    num_str, unit = m.groups()
    num = int(num_str)
    unit = unit.lower().rstrip('s')  # normalize plural

    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError("Unknown time unit in frequency: %r" % unit)

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET:
                # IPv4 loopback range 127.0.0.0/8
                if addr.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                # IPv6 loopback address ::1
                if addr == "::1":
                    return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    return False

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    if strip:
        pattern = pattern.strip()
    return re.compile(pattern)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if args is None:
        args = []
    if isinstance(commands, str):
        commands = [commands]
    for cmd in commands:
        full_cmd = [cmd] + list(args)
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=True
            )
            return result
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed: {e}")
            continue
    raise RuntimeError(f"All commands failed: {commands}")

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    import sys
    data = yaml.safe_dump(obj, Dumper=dumper)
    if sys.version_info[0] < 3:
        if isinstance(data, bytes):
            return data.decode('utf-8')
    return data

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import toml
    import yaml

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(v) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(v) for v in d]
        elif isinstance(d, str):
            return os.path.expandvars(d)
        else:
            return d

    parsed_configs = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                config = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                config = yaml.safe_load(raw)
            elif ext == '.json':
                import json
                config = json.loads(raw)
            else:
                raise ValueError(f'Unsupported config file extension: {ext}')
            if overrides:
                config.update(overrides)
            if resolve_env:
                config = _resolve_env_in_dict(config)
            parsed_configs[fname] = config
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Error parsing configuration file {fname}: {exc}',
                args=(),
                exc_info=exc
            )
            error_records.append(record)

    return parsed_configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return obj

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Gather all handlers defined on the class.
    handlers = {}
    if hasattr(cls, "_protocol_handlers"):
        # Prefer an explicit mapping if provided.
        handlers = dict(cls._protocol_handlers)
    else:
        # Fallback: scan for nested classes with a _protocol_version attribute.
        for name, obj in cls.__dict__.items():
            if isinstance(obj, type) and hasattr(obj, "_protocol_version"):
                handlers[obj._protocol_version] = obj

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Return a single-item dict if the version is supported, otherwise empty.
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
    return handlers

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Ensure we are working with a class
    if not isinstance(candidate, type):
        candidate = type(candidate)

    # Quick check: if candidate is already a subclass of iface, we are good
    try:
        if issubclass(candidate, iface):
            return True
    except TypeError:
        # iface might not be a class; fall back to attribute checks
        pass

    # Inspect the interface's attributes (excluding private and dunder names)
    for name, value in vars(iface).items():
        if name.startswith('_'):
            continue
        if not hasattr(candidate, name):
            if tentative:
                return False
            raise TypeError(
                f"Candidate '{candidate.__name__}' does not implement required "
                f"attribute '{name}' from interface '{iface.__name__}'"
            )
        candidate_attr = getattr(candidate, name)
        # If the interface attribute is a callable, ensure the candidate's
        # attribute is also callable
        if callable(value) and not callable(candidate_attr):
            raise TypeError(
                f"Attribute '{name}' in candidate '{candidate.__name__}' "
                f"should be callable to satisfy interface '{iface.__name__}'"
            )
    return True

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dict is empty')
    # Find the key with the lowest access frequency
    min_key = min(self._freq, key=lambda k: self._freq[k])
    # Remove the key from the cache and its frequency counter
    value = self._data.pop(min_key)
    self._freq.pop(min_key)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if self._head[2] is self._tail:
        raise KeyError('cache is empty')
    node = self._tail[2]
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError as e:
        raise KeyError('dict is empty') from e

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    values = getattr(self, "_in_values", None)
    if not values:
        # No values to match; return a pattern that matches nothing
        return re.compile(r'(?!)')
    escaped = [re.escape(v) for v in values]
    pattern = r'^(?:' + '|'.join(escaped) + r')$'
    return re.compile(pattern)

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter."""
    def _convert(value):
        if hasattr(self, "_style") and self._style:
            try:
                return self._style.format(value)
            except Exception:
                return str(value)
        return str(value)
    return _converting._Converter(_convert)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    # Legacy payload check
    try:
        legacy = json.loads(decode_if_bytes(request.body))
        if "legacy" in legacy:
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""

    # The Matrix API is served under the /_matrix/ path prefix.
    # Some frameworks expose the request path via `path` or `path_info`.
    path = getattr(request, "path", None) or getattr(request, "path_info", None)
    if not path:
        return False

    return path.startswith("/_matrix/")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Regex to match http/https URLs
    url_re = re.compile(r'(https?://[^\s]+)')
    def replace_url(match):
        url = match.group(0)
        # Add target="_blank" attribute to open link in new tab
        return f'<a href="{url}" target="_blank">{url}</a>'
    return url_re.sub(replace_url, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Urllib2HeadRequest(url, headers={'Host': netloc})
    resp = urlopen(req)
    try:
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type')
    finally:
        resp.close()

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    tag = tag.strip()
    if not tag:
        return False
    if len(tag) > 30:
        return False
    import re
    return bool(re.match(r'^[A-Za-z0-9_-]+$', tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url must be provided")
    # Default NodeInfo document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo/1.0.json"
    # Ensure base URL does not end with a slash
    base = url.rstrip("/")
    # Construct the full href
    href = f"{base}{document_path}"
    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message."""
    try:
        # Parse the XML document
        root = etree.fromstring(doc)
    except Exception:
        return False

    # Find the Signature element
    sig_node = root.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    if sig_node is None:
        return False

    try:
        # Load the public key (PEM format)
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    # Create a signature context and verify
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        result = {}
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('aliases', [])
        for link in data.get('links', []):
            rel = link.get('rel')
            href = link.get('href')
            if rel == 'http://webfinger.net/rel/hcard':
                result['hcard_url'] = href
            elif rel == 'http://webfinger.net/rel/avatar':
                result['avatar_url'] = href
            elif rel == 'http://webfinger.net/rel/profile-page':
                result['profile_url'] = href
        return result
    except Exception:
        try:
            root = ET.fromstring(document)
            result = {}
            subject = root.find('.//{*}Subject')
            if subject is not None:
                result['subject'] = subject.text
            aliases = [a.text for a in root.findall('.//{*}Alias')]
            result['aliases'] = aliases
            for link in root.findall('.//{*}Link'):
                rel = link.attrib.get('rel')
                href = link.attrib.get('href')
                if rel == 'http://webfinger.net/rel/hcard':
                    result['hcard_url'] = href
                elif rel == 'http://webfinger.net/rel/avatar':
                    result['avatar_url'] = href
                elif rel == 'http://webfinger.net/rel/profile-page':
                    result['profile_url'] = href
            return result
        except Exception:
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
    try:
        with urllib2.urlopen(url) as page:
            if page.getcode() == 200:
                return page.read().decode('utf-8')
    except Exception:
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    file_list = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, spec_option):
                    file_list.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(file_list)

