def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file must be provided")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Error reading YAML file: {e}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping at the top level")

        required_fields = getattr(cls, 'required_fields', [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.pop('include', {})
    for group, inc_path in includes.items():
        # Resolve relative path based on the current spec file location
        base = getattr(self, '_spec_path', None)
        if base is None:
            base = parser_dict.get('__file__', '.')
        inc_full = os.path.join(os.path.dirname(base), inc_path)
        with open(inc_full, 'r') as f:
            inc_dict = yaml.safe_load(f)
        if inc_dict is None:
            inc_dict = {}
        # Recursively resolve any nested includes in the included spec
        inc_dict = self._include_groups(inc_dict)
        # Merge the included dict into the current parser_dict
        if group in parser_dict and isinstance(parser_dict[group], dict) and isinstance(inc_dict, dict):
            parser_dict[group].update(inc_dict)
        else:
            parser_dict[group] = inc_dict
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Attempt to get a value from the spec if it exists
        spec_val = None
        if hasattr(self, "spec") and self.spec is not None:
            try:
                spec_val = self.spec.get(arg.name)
            except Exception:
                spec_val = None

        if spec_val is not None:
            defaults[arg.name] = spec_val
        else:
            # Fall back to the option's own default if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # Handle nested dictionary options by recursing into their scheme
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {
        # Deprecated option: new option
        'old_arg': 'new_arg',
        'legacy_flag': 'modern_flag',
    }

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Extract option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        # Evaluate the condition
        try:
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
            elif isinstance(cond, str):
                # Evaluate string condition in a safe namespace
                if eval(cond, {}, {'command_name': command_name, 'args': args}):
                    required.append(name)
            else:
                # Treat truthy values as satisfied
                if cond:
                    required.append(name)
        except Exception:
            # If condition evaluation fails, ignore this option
            continue

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # args is expected to be a mapping of argument names to values
    for arg_name, value in args.items():
        # Skip if no value provided
        if value is None:
            continue

        # Retrieve the expected length from the parsed YAML specification
        arg_spec = self.parsed_yaml.get('args', {}).get(arg_name, {})
        expected_len = arg_spec.get('length')
        if expected_len is None:
            continue

        # Ensure the expected length is an integer
        if not isinstance(expected_len, int):
            raise TypeError(
                f"Length for argument '{arg_name}' must be an integer, "
                f"got {type(expected_len).__name__}"
            )

        # Attempt to get the actual length of the value
        try:
            actual_len = len(value)
        except TypeError:
            raise TypeError(
                f"Argument '{arg_name}' does not support len() "
                f"(type {type(value).__name__})"
            )

        # Validate the length constraint
        if actual_len > expected_len:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds "
                f"maximum allowed {expected_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    # Helper to validate a single argument
    def _validate(arg_name, arg_attrs):
        if 'choices' in arg_attrs:
            if arg_name in args:
                val = args[arg_name]
                if val not in arg_attrs['choices']:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {val}. "
                        f"Expected one of {arg_attrs['choices']}"
                    )
    # Handle dict or list of dicts
    if isinstance(arg_defs, dict):
        for name, attrs in arg_defs.items():
            _validate(name, attrs)
    else:  # list of dicts
        for argdict in arg_defs:
            # Each dict in the list should contain a single key/value pair
            name, attrs = list(argdict.items())[0]
            _validate(name, attrs)

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for name, value in args.items():
        min_val = getattr(self, f"{name}_min", None)
        max_val = getattr(self, f"{name}_max", None)
        if min_val is None or max_val is None:
            raise ValueError(f"Missing min or max for argument '{name}'")
        if not (min_val <= value <= max_val):
            raise ValueError(
                f"Argument '{name}' value {value} not in range [{min_val}, {max_val}]"
            )
    return args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated dictionary
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if not extra_vars:
            return vars_dict
        for var in extra_vars:
            if isinstance(var, dict):
                vars_dict.update(var)
            else:
                raise TypeError("Each item in extra_vars must be a dictionary")
        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve a mapping of option names to conversion functions for this parser
    type_map = getattr(self, "_type_mappings", {}).get(parser_name, {})

    for key, val in list(values_dict.items()):
        # If we have a specific conversion function, use it
        if key in type_map:
            cast_func = type_map[key]
            try:
                values_dict[key] = cast_func(val)
                continue
            except Exception:
                # Fall back to generic conversion if the custom cast fails
                pass

        # Generic conversion logic for common types
        if isinstance(val, str):
            lowered = val.lower()
            if lowered in ("true", "false"):
                values_dict[key] = lowered == "true"
            else:
                try:
                    values_dict[key] = int(val)
                except ValueError:
                    try:
                        values_dict[key] = float(val)
                    except ValueError:
                        # leave as string if no conversion applies
                        pass
    # values_dict is modified in place; no return needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # locate the plugin spec file
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # load the spec
    with open(spec_file, "r", encoding="utf-8") as f:
        if spec_file.endswith(".json"):
            spec = json.load(f)
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to load YAML plugin spec")
            spec = yaml.safe_load(f)

    # helper to flatten nested dicts
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if norm_path == norm_root:
        return ''
    if norm_path.startswith(norm_root + os.sep):
        return norm_path[len(norm_root) + 1:]
    raise ValueError(f"Path '{path}' does not start with root '{root}'.")
